/* Same geometry powers developer views, exports and the normal map atlas. */
window.drawMapDebugV14=function(canvas,mode='NORMAL_MAP',options={}){let C=GAME_CONFIG,M=C.map,g=canvas.getContext('2d'),size=canvas.width,scale=size/C.world;g.setTransform(scale,0,0,scale,0,0);g.fillStyle='#10251f';g.fillRect(0,0,C.world,C.world);if(['NORMAL_MAP','JUNGLE_MAP','WALL_BRUSH_MAP'].includes(mode))g.drawImage(createRiftGround(C),0,0,C.world,C.world);g.font='80px sans-serif';g.lineWidth=12;
if(['WALL_COLLISION_MAP','WALL_BRUSH_MAP','PROJECTILE_COLLISION_MAP','JUNGLE_MAP','VISION_MAP'].includes(mode))for(let w of M.walls){let p=w.polygonVertices;if(!p)continue;g.beginPath();p.forEach((v,i)=>i?g.lineTo(v.x,v.y):g.moveTo(v.x,v.y));g.closePath();g.fillStyle=w.collisionType==='TRANSPARENT_COLLISION_WALL'?'#54becd88':w.collisionType==='TEAM_RESTRICTED_WALL'?'#e3bb5777':'#a0aea5aa';g.fill();g.strokeStyle='#d8e7da';g.stroke()}
if(['BRUSH_MAP','WALL_BRUSH_MAP','JUNGLE_MAP','VISION_MAP'].includes(mode))for(let b of M.bushes){g.beginPath();b.polygonVertices.forEach((p,i)=>i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y));g.closePath();g.fillStyle='#77bf6c99';g.fill();g.strokeStyle='#b2e9a5';g.stroke();g.fillStyle='#edf6db';g.fillText(b.brushId,b.x-b.w/2,b.y)}
if(mode==='NAVIGATION_MAP'){let n=100,step=C.world/n;for(let y=0;y<n;y++)for(let x=0;x<n;x++){let blocked=M.queryWalls((x+.5)*step,(y+.5)*step,24).some(w=>M.wallContains(w,(x+.5)*step,(y+.5)*step,24));g.fillStyle=blocked?'#934d55':'#427765';g.fillRect(x*step,y*step,step-4,step-4)}}
if(mode==='VISION_MAP')for(let f of M.faelights){g.beginPath();g.arc(f.x,f.y,f.radius,0,Math.PI*2);g.fillStyle='#e3c77d33';g.fill();g.fillStyle='#ffe2a2';g.fillText(f.id,f.x,f.y)}
for(let c of M.camps){g.beginPath();g.arc(c.x,c.y,mode==='JUNGLE_MAP'?c.leashRegion.radius:120,0,Math.PI*2);g.strokeStyle=c.kind==='blue'?'#67aaff':c.kind==='red'?'#ec8666':'#d3b68a';g.stroke();g.fillStyle='#f0e7cc';g.font='75px sans-serif';g.fillText(c.campId,c.x-160,c.y-140)}
for(let team=0;team<2;team++){g.fillStyle=team?'#ff929b':'#83d8ff';for(let lane=0;lane<3;lane++)for(let tier=0;tier<3;tier++){let p=M.towerPoint(lane,team,tier);g.fillRect(p.x-50,p.y-50,100,100)}let p=M.bases[team];g.beginPath();g.arc(p.x,p.y,180,0,Math.PI*2);g.fill()}
if(options.path?.length){g.strokeStyle='#ffe890';g.lineWidth=30;g.beginPath();options.path.forEach((p,i)=>i?g.lineTo(p.x,p.y):g.moveTo(p.x,p.y));g.stroke()}g.setTransform(1,0,0,1,0,0);return canvas};
window.findMapDebugPath=function(start,end,r=24){let M=GAME_CONFIG.map,size=125,n=Math.ceil(GAME_CONFIG.world/size),key=(x,y)=>y*n+x,s=[Math.floor(start.x/size),Math.floor(start.y/size)],t=[Math.floor(end.x/size),Math.floor(end.y/size)],queue=[s],seen=new Set([key(...s)]),from=new Map,found=null;for(let k=0;k<queue.length;k++){let a=queue[k];if(Math.abs(a[0]-t[0])+Math.abs(a[1]-t[1])<=1){found=a;break}for(let [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){let x=a[0]+dx,y=a[1]+dy,id=key(x,y),px=(x+.5)*size,py=(y+.5)*size;if(x<0||y<0||x>=n||y>=n||seen.has(id)||M.queryWalls(px,py,r).some(w=>M.wallContains(w,px,py,r)))continue;seen.add(id);from.set(id,a);queue.push([x,y])}}let out=[];while(found){out.unshift({x:(found[0]+.5)*size,y:(found[1]+.5)*size});found=from.get(key(...found))}return out};
